process_name = "{{input.process_name}}"
min_count = int("{{input.min_count}}" or "1")

count = 0
pids = []
for pid in os.listdir("/proc"):
    if not pid.isdigit():
        continue
    try:
        with open(f"/proc/{{pid}}/comm", "r") as f:
            comm = f.read().strip()
        if process_name in comm:
            count += 1
            pids.append(int(pid))
    except (IOError, OSError):
        continue

result = {{
    "process": process_name,
    "count": count,
    "pids": pids[:20],
    "min_expected": min_count,
    "status": "ok" if count >= min_count else "critical",
}}
print(json.dumps(result))
if count < min_count:
    sys.exit(1)

import json
import sys

port = "{{input.port}}"
threshold = int("{{input.threshold}}" or "1000")

states = {{}}
total = 0
tcp_state_map = {{
    "01": "ESTABLISHED", "02": "SYN_SENT", "03": "SYN_RECV",
    "04": "FIN_WAIT1", "05": "FIN_WAIT2", "06": "TIME_WAIT",
    "07": "CLOSE", "08": "CLOSE_WAIT", "09": "LAST_ACK",
    "0A": "LISTEN", "0B": "CLOSING",
}}

try:
    with open("/proc/net/tcp", "r") as f:
        lines = f.readlines()[1:]  # skip header
    for line in lines:
        parts = line.split()
        local_port = int(parts[1].split(":")[1], 16)
        state_code = parts[3]
        if port and str(local_port) != port:
            continue
        state = tcp_state_map.get(state_code, "UNKNOWN")
        states[state] = states.get(state, 0) + 1
        total += 1
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)

result = {{
    "total": total,
    "by_state": states,
    "threshold": threshold,
    "status": "critical" if total > threshold else "ok",
}}
print(json.dumps(result))
if total > threshold:
    sys.exit(1)

