import json
import socket
import sys

primary_host = "{{input.primary_host}}"
primary_port = int("{{input.primary_port}}")
replica_host = "{{input.replica_host}}"
replica_port = int("{{input.replica_port}}")
timeout = int("{{input.timeout}}" or "5")

results = {{}}
for label, host, port in [("primary", primary_host, primary_port), ("replica", replica_host, replica_port)]:
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(timeout)
        result = sock.connect_ex((host, port))
        sock.close()
        results[label] = {{"host": host, "port": port, "reachable": result == 0}}
    except Exception as e:
        results[label] = {{"host": host, "port": port, "reachable": False, "error": str(e)}}

both_up = results.get("primary", {{}}).get("reachable", False) and results.get("replica", {{}}).get("reachable", False)
output = {{
    "status": "ok" if both_up else "error",
    "primary": results.get("primary", {{}}),
    "replica": results.get("replica", {{}}),
}}
print(json.dumps(output))
if not both_up:
    sys.exit(1)

